// Strict one-to-one correlation: every requested plan produces exactly one outcome.

function parseBody(body) {
  if (body && typeof body === "object") return body;
  const text = String(body ?? "").trim();
  if (!text) return null;
  try { return JSON.parse(text); } catch {}
  let last = null;
  for (const line of text.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("data:")) continue;
    const payload = trimmed.slice(5).trim();
    if (!payload || payload === "[DONE]") continue;
    try { last = JSON.parse(payload); } catch {}
  }
  return last;
}

function decodeNested(value, depth = 0) {
  if (depth > 3) return value;
  if (typeof value === "string") {
    try { return decodeNested(JSON.parse(value), depth + 1); }
    catch { return value; }
  }
  if (value && typeof value === "object" && !Array.isArray(value) &&
      typeof value.result === "string") {
    return {...value, result: decodeNested(value.result, depth + 1)};
  }
  return value;
}

function normalizeResponse(request, response, responseIndex) {
  const metadata = {
    rpcId: request.rpcId,
    planIndex: request.planIndex,
    planCount: request.planCount,
    planId: request.planId,
    subQuestion: request.subQuestion,
    question: request.question,
    selectedTool: request.selectedTool,
    requestArguments: request.requestArguments ?? {},
    requestBody: request.rpcBody ?? null,
    responseMode: request.responseMode,
    responseIndex
  };
  const body = response?.body ?? response?.data;
  const message = parseBody(body);
  const statusCode = Number(response?.statusCode ?? 200);
  const bad = error => ({json:{...metadata, ok:false, error}});
  if (statusCode >= 400) {
    return bad(`MCP HTTP ${statusCode}: ${String(body ?? "").slice(0,500)}`);
  }
  if (!message || typeof message !== "object") {
    return bad("MCP response could not be parsed.");
  }
  if (message.id !== request.rpcId) {
    return bad("MCP JSON-RPC response ID does not match its request.");
  }
  if (message.error) {
    return bad(`MCP JSON-RPC error ${message.error.code}: ${message.error.message}`);
  }
  const result = message.result ?? {};
  const textContent = Array.isArray(result.content)
    ? result.content.filter(x => x?.type === "text").map(x => x.text).join("\\n")
    : "";
  if (result.isError) {
    return bad(`MCP tool execution error: ${textContent || "Unknown tool error"}`);
  }
  let data = result.structuredContent;
  if (data === undefined) data = textContent || result;
  data = decodeNested(data);
  if (data === null || data === undefined || data === "") {
    return bad("MCP returned no readable result.");
  }
  return {json:{...metadata, ok:true, data}};
}

const requests = $("Build Tool Call").all().map(item => item.json);
const responseItems = $input.all();
const responses = responseItems.map(item => item.json ?? {});
if (!requests.length) throw new Error("No originating MCP requests were found.");

const requestById = new Map();
for (const request of requests) {
  if (request.rpcId === undefined || request.rpcId === null ||
      requestById.has(String(request.rpcId))) {
    throw new Error("Originating MCP requests contain a missing or duplicate JSON-RPC ID.");
  }
  requestById.set(String(request.rpcId), request);
}

const responseBuckets = new Map();
const unidentified = [];
const unexpectedIds = [];
for (let index = 0; index < responses.length; index++) {
  const response = responses[index];
  const paired = responseItems[index]?.pairedItem;
  const pairedEntries = Array.isArray(paired) ? paired : paired ? [paired] : [];
  const pairedIndexes = pairedEntries
    .map(entry => Number(entry?.item))
    .filter(value => Number.isInteger(value) && value >= 0 && value < requests.length);

  // n8n's continueRegularOutput preserves failed HTTP items and their
  // paired-item lineage. Use that lineage only for explicit transport errors.
  if (response.error && pairedIndexes.length === 1) {
    const request = requests[pairedIndexes[0]];
    const key = String(request.rpcId);
    if (!responseBuckets.has(key)) responseBuckets.set(key, []);
    responseBuckets.get(key).push({
      response: {
        ...response,
        body: response.error.message ?? response.error.description ?? String(response.error),
        statusCode: 599
      },
      index
    });
    continue;
  }

  const message = parseBody(response.body ?? response.data);
  const id = response.rpcId ?? message?.id;
  if (id === undefined || id === null) {
    unidentified.push({response,index});
    continue;
  }
