  const key = String(request.rpcId);
  const matches = responseBuckets.get(key) ?? [];
  if (matches.length === 0) {
    const reason = unidentified.length
      ? "MCP response omitted JSON-RPC ID; multi-plan correlation is ambiguous."
      : unexpectedIds.length
        ? "No response matched this plan; unexpected JSON-RPC IDs were received: " + unexpectedIds.join(", ")
