      rpcId:request.rpcId, planIndex:request.planIndex, planCount:request.planCount,
      planId:request.planId, subQuestion:request.subQuestion, question:request.question,
      selectedTool:request.selectedTool, requestArguments:request.requestArguments ?? {},
