// Main Processing
// ============================================================

const output = [];

for (let index = 0; index < inputItems.length; index++) {
  const response = inputItems[index].json ?? {};

  // Match the originating request by JSON-RPC id; fall back to preserved metadata
  // and only then to item order.
  const matchedBuild =
    response.rpcId != null
      ? buildItems.find(item => item.json?.rpcId === response.rpcId)
      : null;

  const build =
    matchedBuild?.json ??
    buildItems[index]?.json ??
    {};

  const selectedTool =
    response.selectedTool ??
    build.selectedTool ??
    build.plan?.tool ??
    null;

  const args =
    response.requestArguments ??
    build.rpcBody?.params?.arguments ??
    build.arguments ??
    build.plan?.arguments ??
    {};

  const question = response.question ?? build.question ?? null;

  const operation =
    selectedTool === "analytics_query"
      ? args.operation ?? null
      : null;

  if (response.ok === false) {
    const errorText = String(
      response.error?.message ??
      response.error ??
      response.message ??
      "Unknown MCP error"
    );

    const queryJson = selectedTool === "analytics_query"
      ? JSON.stringify(args)
      : JSON.stringify({ tool: selectedTool, ...args });

    const facts = {
      tool: selectedTool,
      dataset_id: args.dataset_id ?? null,
      operation,
      recognized: false,
      execution_status: "failure",
      error: errorText,
      count: null,
      row_count: null,
      total_records: null,
      shown: 0,
      columns: [],
      rows: [],
      rows_sample: []
    };

    output.push({
      json: {
        question,
        selectedTool,
        operation,
        rpcId: response.rpcId ?? build.rpcId ?? null,
        correlationStatus: response.correlationStatus ?? "unknown",
        planIndex: response.planIndex ?? build.planIndex ?? index,
        planCount: response.planCount ?? build.planCount ?? buildItems.length,
        planId: response.planId ?? build.planId ?? `plan_${index + 1}`,
        subQuestion: response.subQuestion ?? build.subQuestion ?? question,
        queryJson,
        recognized: false,
        executionSuccess: false,
        error: errorText,
        countValue: null,
        rowCount: null,
        totalRecords: null,
        shown: 0,
        columns: [],
        tableMarkdown: `اجرای این بخش از درخواست ناموفق بود: ${errorText}`,
        factsJson: JSON.stringify(facts)
      }
    });

    continue;
  }

  const normalized = unwrapResponse(response);
  const data = normalized.data;
  const rawData = normalized.raw;

  if (isObject(data) && data.status === "error") {
    const errorText = String(data.error?.message ?? data.error?.detail ?? data.error ?? "MCP tool returned an error.");
    const facts = { tool: selectedTool, dataset_id: args.dataset_id ?? null, operation, recognized: false, execution_status: "failure", error: errorText, rows: [], rows_sample: [] };
    output.push({
      json: {
        question, selectedTool, operation,
        rpcId: response.rpcId ?? build.rpcId ?? null,
        correlationStatus: response.correlationStatus ?? "unknown",
        planIndex: response.planIndex ?? build.planIndex ?? index,
        planCount: response.planCount ?? build.planCount ?? buildItems.length,
        planId: response.planId ?? build.planId ?? ("plan_" + (index + 1)),
        subQuestion: response.subQuestion ?? build.subQuestion ?? question,
        responseMode: response.responseMode ?? build.responseMode ?? "combined",
        queryJson: JSON.stringify(args),
        recognized: false, executionSuccess: false, error: errorText,
        countValue: null, rowCount: null, totalRecords: null, shown: 0,
        columns: [], rows: [], tableMarkdown: "اجرای ابزار ناموفق بود: " + errorText,
        factsJson: JSON.stringify(facts)
      }
    });
    continue;
  }

  let result = null;

  if (selectedTool === "search_elasticsearch") {
    result = renderSearch(data, args);
  } else if (selectedTool === "get_top_market_skills") {
    result = renderTopSkills(data);
  } else if (selectedTool === "analytics_query") {
    if (operation === "count") {
      result = renderCount(data);
    } else if (operation === "select") {
      result = renderSelect(data, args);
    } else if (operation === "aggregate") {
      result = renderAggregate(data, args);
    }
  } else {
    // Future MCP tools can use a generic result renderer
    // without changing the existing specialized renderers.
    result = renderGenericTool(data);
  }

  const recognized = result !== null;

  const queryJson =
    selectedTool === "analytics_query"
      ? JSON.stringify(args)
      : JSON.stringify({
          tool: selectedTool,
          ...args
        });

const allRows = Array.isArray(result?.rows)
  ? result.rows
  : [];

const facts = {
  tool: selectedTool,
  dataset_id: args.dataset_id ?? null,
  operation,
  recognized,

  count: result?.countValue ?? null,
  row_count: result?.rowCount ?? null,
  total_records: result?.totalRecords ?? null,
  shown: result?.shown ?? 0,

  columns: result?.columns ?? [],

  // Complete structured dataset for downstream analysis
  rows: allRows,

  // Limited preview for lightweight inspection
  rows_sample: allRows.slice(0, MAX_SAMPLE),

  ...(result?.extra ?? {})
};

  const tableMarkdown = recognized
    ? result.tableMarkdown
    : [
        "ساختار پاسخ ابزار با قالب‌های شناخته‌شده تطبیق داده نشد.",
        "پاسخ خام ابزار برای بررسی و توسعه قالب نمایش:",
        "",
        "```json",
        (typeof rawData === "string" ? rawData : JSON.stringify(rawData ?? data, null, 2)).slice(0, MAX_RAW_LENGTH),
        "```"
      ].join("\n");

  output.push({
    json: {
      question,
      selectedTool,
      operation,
      rpcId: response.rpcId ?? build.rpcId ?? null,
        correlationStatus: response.correlationStatus ?? "unknown",
      planIndex: response.planIndex ?? build.planIndex ?? index,
      planCount: response.planCount ?? build.planCount ?? buildItems.length,
      planId: response.planId ?? build.planId ?? `plan_${index + 1}`,
      subQuestion: response.subQuestion ?? build.subQuestion ?? question,
      responseMode: response.responseMode ?? build.responseMode ?? "combined",
      queryJson,
      recognized,
      executionSuccess: true,

      countValue: result?.countValue ?? null,
      rowCount: result?.rowCount ?? null,
      totalRecords: result?.totalRecords ?? null,
      shown: result?.shown ?? 0,

      columns: result?.columns ?? [],
      rows: allRows,
      tableMarkdown,

      factsJson: JSON.stringify(facts)
    }
  });
}

// Preserve the original user-request order even if MCP responses arrive out of order.
output.sort((a, b) =>
  Number(a.json.planIndex ?? 0) - Number(b.json.planIndex ?? 0)
);

